example_item.example_item_data:
% Two minutes of clean simulated signal: nearly every window is usable.
recording = ecglab.simulate('Seconds', 120, 'Seed', 1);
q = ecglab.quality(recording);
fprintf('%.0f%% usable\n', 100 * q.usableFraction)

% A clean start and a noisy end: the longest good stretch is the clean part.
recording = ecglab.simulate('Seconds', 180, 'Seed', 2);
N = size(recording.samples, 1);
third = round(2 * N / 3);
recording.samples(third + 1:end, 1) = recording.samples(third + 1:end, 1) ...
  + 0.5 * randn(N - third, 1);
q = ecglab.quality(recording);
good = q.good
